function showCharacter(tab){const w=openModal('<div class="meter-entry-wrap">'+meterEntry()+'</div>'+characterPanel(game)+'<div class="person-skills">'+(mobile?.active?'<button class="outline-button" data-shell="mobile">Touchbuttons belegen</button>':'')+'<button class="outline-button" data-reset-bar>'+PANEL_UI.barResetButton+'</button>'+skillbookPanel(game,selectedSkill,pendingSlot)+'</div><div class="person-talents">'+talentsPanel(game)+'</div><div class="person-clan">'+clanMenu(game,clanPick||game.member.id)+'</div>',false,'person');paintRpg();document.querySelectorAll('[data-clan-portrait]').forEach(cv=>{if(paintHeroPortrait(cv,cv.dataset.clanPortrait,equipmentAppearance(game.rpg.equipment,ITEMS)))return;cv.getContext('2d').clearRect(0,0,cv.width,cv.height);drawHero(cv.getContext('2d'),cv.width/2,cv.height*.83,0,{facing:1,classId:cv.dataset.clanPortrait},false,cv.width/60);});selectTab(w,tab);}
function settingsPanel(){return `<div class="help-settings"><p>${PANEL_UI.settingsIntro}</p>${meterEntry()}${hudEntry()}<button type="button" data-shell="mobile">Steuerung & Touchbuttons</button><button type="button" data-shell="install">Als App installieren</button><button type="button" data-setting-toggle="autoLoot" aria-pressed="${game.settings.autoLoot}">Auto-Loot: ${game.settings.autoLoot?'an':'aus'}</button><button type="button" data-setting-toggle="sct" aria-pressed="${game.settings.sct!==false}">Kampftext am Helden: ${game.settings.sct!==false?'an':'aus'}</button><a href="./combat-fx-demo.html" target="_blank" rel="noopener">Kniffe & Effekte ?</a><a href="./redesign-demo.html" target="_blank" rel="noopener">Helden & Ausr?stung ?</a><button type="button" data-settings="sound">Ton an / aus</button><button type="button" data-settings="fullscreen">Vollbild</button>${mobile?.active?'<button type="button" data-settings="touchmenu">App-Status & Update</button>':''}<a href="./world-forge.html" target="_blank" rel="noopener">Weltschmiede ↗</a><button type="button" class="help-settings-admin" data-shell="admin">Admin · Neustart, Sicherung, Trainingsarena</button><p class="build-line" data-build>${buildLabel(BUILD)}</p></div>`;}
function showGameMenu(){game.stopAuto?.();game.keys.clear();mobile?.stop();const w=openModal(gameMenu({account:!!online?.account}),false,'menu');if(!mobile?.active){w.el.style.left=Math.max(8,(innerWidth-w.el.offsetWidth)/2)+'px';w.el.style.top=Math.max(8,(innerHeight-w.el.offsetHeight)/2)+'px';popups.clamp(w);}w.body.querySelector('button')?.focus({preventScroll:true});}
function menuKey(e){if(!popups.isOpen('menu'))return false;if(e.key==='Escape'||e.key.toLowerCase()==='p'){e.preventDefault();if(!e.repeat)closeModal('menu');return true;}if(e.key==='Tab'){e.preventDefault();const buttons=[...popups.get('menu').el.querySelectorAll('button')].filter(b=>!b.disabled&&b.getClientRects().length),i=buttons.indexOf(document.activeElement);buttons[(i+(e.shiftKey?-1:1)+buttons.length)%buttons.length]?.focus();}return true;}
function showPanel(id,toggle=false){if(id==='settings'){showGuide(PANEL_UI.settings);return;}if(id==='mobile'){mobile?.editor();return;}if(id==='install'){pwa?.show();return;}const show=({map:showMap,quest:showJournal,person:showCharacter,book:showBook,bag:showInventory,base:showBase,guide:showGuide,menu:showGameMenu,clan:showClan,admin:showAdmin,talents:showTalents})[id];if(!show)return;const windowId=({talents:'person',clan:'person',book:'person',base:'quest'})[id]||id;if(['person','bag','book','quest','base','map','guide'].includes(windowId))lastTab=windowId;if(toggle&&popups.isOpen(windowId)&&!['talents','clan','book','base'].includes(id)){popups.close(windowId);return;}show();popups.focus(windowId);}
popups.onTab=id=>showPanel(id);
function selectItem(id){selectedItem=id;const body=popups.get('bag')?.body;if(!body)return;const tmp=document.createElement('div');tmp.innerHTML=inventoryPanel(game,id);const selected=tmp.querySelector('.selected-item');openModal(itemTooltip(game,id)+selected.outerHTML,false,'inspection').inspectedItem=id;paintRpg();body.querySelectorAll('[data-item]').forEach(b=>b.classList.toggle('selected',b.dataset.item===id));}
function selectSkill(id){if(mobile?.active){openModal(skillTooltip(game,id,true)+'<button class="gold-button" data-shell="mobile">Touchbuttons belegen</button>',false,'touchhelp');paintRpg();return;}if(id&&SPECIAL_KEYS[id]!==undefined){toast('Sonderaktion mit festem Platz: ['+keyFor(game,id)+'].');return;}if(pendingSlot!==null&&id&&SPECIAL_KEYS[id]===undefined){const slot=pendingSlot;pendingSlot=null;if(bindSkill(game,id,slot)){selectedSkill=id;events();toast('Kniff liegt jetzt auf ['+SLOT_KEYS[slot]+'].');return;}}selectedSkill=id;modal.querySelectorAll('[data-book-skill]').forEach(b=>b.classList.toggle('selected',b.dataset.bookSkill===id));const label=modal.querySelector('.book-actionbar>small');if(label)label.textContent='Ausgewählt: '+(game.skills.find(s=>s.id===id)?.name||'Platz leeren');}
function refreshPanels(){if(popupControls?.dragging)return;const inspected=popups.get('inspection')?.inspectedItem;if(inspected&&!game.rpg.inventory.some(e=>e.id===inspected))popups.close('inspection');const focused=document.activeElement,search=focused?.matches('[data-bag-search]');popupControls?.hide();for(const [id,show] of Object.entries({bag:showInventory,person:showCharacter,quest:showJournal}))if(popups.isOpen(id))show();if(popups.isOpen('loot')){if(game.rpg.loot.some(b=>b.id===selectedLootId))showLoot(selectedLootId);else popups.close('loot');}if(inspected&&popups.isOpen('inspection'))selectItem(inspected);if(search)popups.get('bag')?.body.querySelector('input')?.focus({preventScroll:true});}

