modal.addEventListener('click',e=>{const button=e.target.closest('button');if(e.target.closest('[data-close]'))closeModal();if(button?.id==='acceptQuest'){if(game.dead||distance(game.player,world.npc)>=50){toast('Geh wieder zu '+world.npc.name+', um den Auftrag anzunehmen.');return;}game.acceptQuest();closeModal();events();toast('Auftrag angenommen. Die Gegner warten an den markierten Orten.');}if(button?.id==='claimQuest'){if(game.dead||distance(game.player,world.npc)>=50){toast('Die Belohnung gibt es bei '+world.npc.name+'.');return;}showReward(game.rewardKey());}if(button?.id==='respawn'){game.respawn();closeModal();events();}});
modal.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.hubRoute){const h=world.hubs.find(h=>h.id===b.dataset.hubRoute);if(h){closeModal();game.navigate(h);}return;}if(b.dataset.memberWear){clanPick=null;closeModal();game.switchMember(b.dataset.memberWear);events();return;}if(b.dataset.memberPick){clanPick=b.dataset.memberPick;showCharacter(PANEL_UI.band);return;}if(b.dataset.member){clanPick=null;closeModal();game.switchMember(b.dataset.member);events();return;}if(b.dataset.mainRoute){const camp=world.camps.find(c=>c.type===b.dataset.mainRoute&&!c.questId);if(camp){closeModal();game.navigate(camp.approach||camp);toast('Route zum Lagerrand. Vor Ort wählst du selbst deinen Gegner.');}return;}const accept=b.dataset.acceptSide,claim=b.dataset.claimSide,track=b.dataset.trackSide,route=b.dataset.routeGiver;if(accept){closeModal();const ok=game.acceptSideQuest(accept);events();toast(ok?'Auftrag angenommen. Die goldene Wegmarke zeigt dein Ziel.':'Geh zum Questgeber zurück.');}if(claim){showReward(claim);}if(track){game.trackedQuest=track;save();closeModal();}if(route){const q=world.quests.find(q=>q.id===route),s=game.sideQuests[route];if(s.accepted&&!s.claimed)game.trackedQuest=route;const p=s.accepted&&!s.claimed?game.questDestination().point:q.giver;showMap({id:'quest:'+q.id,title:q.title,point:p,detail:s.accepted?'Dein Auftragsziel':q.giver.name});}});
document.addEventListener('keydown',e=>{if(!game||startScreen?.isOpen||menuKey(e))return;if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){if(e.key==='Escape'){e.preventDefault();e.target.blur();closeModal();}return;}const key=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright','tab',' ','1','2','3','4','5','6','7','8','9','0','q'].includes(key))e.preventDefault();if(['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright'].includes(key))game.keys.add(key);if(e.repeat)return;
  if((key==='v'||e.code==='KeyV')&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();meterUI.opened?meterUI.close():meterUI.open({focus:false});return;}if(key==='tab')game.selectNext(e.shiftKey);if(key==='n')showPanel('talents',true);if(key==='m')showPanel('map',true);if(key==='c')showPanel('person',true);if(key==='i')showPanel('bag',true);if(key==='k')showPanel('book',true);if(key==='j')showPanel('quest',true);if(key==='b')showPanel('base',true);if(key==='r'){game.showAggro=!game.showAggro;toast(game.showAggro?'Aggro-Radius des gewählten aggressiven Ziels sichtbar.':'Aggro-Radius ausgeblendet.');}if(key==='h')showPanel('guide',true);if(key==='p'){showPanel('menu',true);return;}if(key==='escape'){e.preventDefault();if(game.casting){game.casting=null;return;}if(game.aiming){game.aiming=null;game.aimPoint=null;return;}
   // Esc schließt zuerst offene Fenster; aus der Welt öffnet es das Spielmenü und beendet den Autoangriff.
   if(e.shiftKey){popups.closeAll();return;}
   if(popups.top()){closeModal();return;}
   showGameMenu();events();updateUI();return;}if(key==='f'&&game.activity){activityInput(game);events();return;}if(key==='f'){const bag=nearestLoot(game);if(e.shiftKey&&bag){takeLoot(game,bag.id);events();}else if(['dialog','memory','loot','death'].some(id=>popups.isOpen(id)))closeModal(popups.top());else speak();}const action=Object.keys(SPECIAL_KEYS).find(id=>SPECIAL_KEYS[id]===key)||(mobile?.active&&SLOT_KEYS.includes(key)?mobile.slotForKey(SLOT_KEYS.indexOf(key)):actionBar(game)[SLOT_KEYS.indexOf(key)]);if(action)game.action(action);
});document.addEventListener('keyup',e=>game?.keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{game?.keys.clear();if(game)game.touchMove=null;});document.addEventListener('visibilitychange',()=>{syncPause();if(document.hidden&&game)save();});window.addEventListener('pagehide',()=>game&&save());window.addEventListener('beforeunload',()=>game&&save());
// Mobile browsers may terminate a backgrounded page without beforeunload.
setInterval(()=>{if(game&&!game.paused)save();},5000);
$('#world').addEventListener('pointerdown',e=>{if(!game||game.paused||game.dead)return;$('#world').focus({preventScroll:true});const p=renderer.screenToWorld(e.clientX,e.clientY);if(inKiosk(game)){if(e.button===0||e.button===2){if(distance(p,KIOSK_ROOM.exit)<25){if(distance(game.player,KIOSK_ROOM.exit)<=KIOSK_ROOM.range){game.leaveKiosk();events();}else game.navigate(KIOSK_ROOM.exit);}else if(Math.hypot(p.x-KIOSK_ROOM.keeper.x,p.y-(KIOSK_ROOM.keeper.y-22))<28){if(distance(game.player,KIOSK_ROOM.service)<=KIOSK_ROOM.range)showShop();else game.navigate(KIOSK_ROOM.service);}else game.navigate(p);}return;}const door=kioskEntrance(game),house=game.world.places?.kiosk?.props?.find(p=>p.kind==='kiosk');if((e.button===0||e.button===2)&&house&&p.x>=house.x-house.w/2&&p.x<=house.x+house.w/2&&p.y>=house.y-house.h/2-65&&p.y<=house.y+house.h/2+20){if(distance(game.player,door)<=KIOSK_ROOM.range){game.enterKiosk();events();}else game.navigate(door);return;}if(game.aiming){if(e.button===2){game.aiming=null;game.aimPoint=null;}else if(e.button===0){game.action(game.aiming,p);events();}return;}if(e.button===0){const merchant=merchantActorPoint(game),counter=merchantPoint(game);if(merchant&&Math.hypot(p.x-merchant.x,p.y-(merchant.y-22))<30){if(distance(game.player,counter)<=SHOP_RULES.range)showShop();else game.navigate(counter);return;}const bag=game.rpg.loot.find(b=>distance(b,p)<13);if(bag){if(distance(bag,game.player)<=43)showLoot(bag.id);else game.navigate(bag);return;}if(selectUnitAt(game,p.x,p.y))events();else{if(game.target||game.friend){game.target=null;clearFriend(game);game.stopAuto?.();events();}/* Klick auf leere Fläche hebt die Zielwahl auf (Nutzerbefund 2026-09-18) */if(e.pointerType==='touch')game.navigate(p);}}else if(e.button===2){const u=selectUnitAt(game,p.x,p.y);if(u?.kind==='enemy'){game.startAttack();events();}else if(u){friendAction(u);events();}else game.navigate(p);}});/* Rechtsklick universal (context-menu.js): Direktwirkungen bleiben bei ihren Handlern, hier stehen nur die Menüs. */
mountContextMenu(target=>{
 if(!game)return null;const so=online?.social,q=s=>target.closest?.(s);
 if(q('#world')||q('[data-item],[data-equipped],[data-loot-item],[data-action-slot],[data-bind-slot],[data-talent],.popup-shop'))return true;
 const member=q('[data-party-name]');if(member)return playerMenu(member.dataset.partyName);
 const line=q('[data-chat-player]');if(line&&so?.connected())return playerMenu(line.dataset.chatPlayer);
 if(q('#chatWindow'))return {title:'Chatfenster',items:[{label:'Einrichten',action:()=>chatWindow?.configure()},{label:'Lage und Größe zurücksetzen',action:()=>chatWindow?.resetPlace()},so?.connected()?{label:'Spielerliste',action:()=>so.who()}:null]};
 if(q('.party-frames'))return {title:'Gruppe',items:[{label:'Gruppe verlassen',danger:true,action:()=>so?.leave()}]};
 if(q('.player-panel'))return {title:game.member.name,items:[{label:'Figur',action:()=>showPanel('person')},{label:'Talente',action:()=>showPanel('talents')},{label:'Rucksack',action:()=>showPanel('bag')},so?.party().members.length?{separator:true}:null,so?.party().members.length?{label:'Gruppe verlassen',danger:true,action:()=>so.leave()}:null]};
 if(q('#targetPanel')){const f=game.friend,player=f?.player?f.ref?.name:null;return {title:$('#targetName').textContent||'Ziel',items:[...(player&&so?playerMenu(player).items.slice(0,-2):[]),game.target?{label:game.autoAttack.enabled?'Angriff stoppen':'Angreifen',action:()=>{game.autoAttack.enabled?game.stopAuto():game.startAttack();events();}}:null,{label:'Ziel abwählen',action:()=>{game.target=null;game.friend=null;game.stopAuto?.();events();}}]};}
 if(q('#miniButton'))return {title:'Karte',items:[{label:'Weltkarte öffnen',action:()=>showPanel('map')},{label:'Zum Auftragsziel laufen',disabled:!game.destination?.(),action:()=>{game.navigateDestination();events();}}]};
 if(q('.quest-panel'))return {title:'Aufträge',items:[{label:'Auftragsbuch öffnen',action:()=>showPanel('quest')},{label:'Zum Ziel laufen',disabled:!game.destination?.(),action:()=>{game.navigateDestination();events();}}]};
 return null;
});
document.querySelectorAll('[data-move]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);game?.keys.add(b.dataset.move);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>game?.keys.delete(b.dataset.move));});
modal.addEventListener('submit',e=>{if(e.target.closest('[data-online-form]'))online?.handle(e);});
modal.addEventListener('click',e=>{if(e.target.closest('[data-online], [data-online-submit]')){online?.handle(e);return;}const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.talent){if(mobile?.active){const known=game.rpg.talents.learned.includes(d.talent);openModal(talentTooltip(game,d.talent,true)+'<button class="gold-button" data-confirm-talent="'+d.talent+'">'+(known?'Punkt zurücknehmen':'Talent lernen')+'</button>',false,'touchhelp');}else{if(!learnTalent(game,d.talent))toast('Punkt, vorheriges Talent und freie Hände nötig.');events();requestAnimationFrame(()=>document.querySelector('[data-talent="'+d.talent+'"]')?.dispatchEvent(new PointerEvent('pointerover',{bubbles:true,pointerType:'mouse'})));}}if(d.confirmTalent){const ok=game.rpg.talents.learned.includes(d.confirmTalent)?unlearnTalent(game,d.confirmTalent):learnTalent(game,d.confirmTalent);if(ok)popups.close('touchhelp');else toast('Voraussetzungen, freie Punkte und Folgetalente beachten.');events();}if('resetBar' in d){game.rpg.actionBars[game.member.id]=null;actionBar(game);buildActions();toast(PANEL_UI.barReset);events();}if(d.viewTree){viewTalentTree(d.viewTree);refreshPanels();paintRpg();}if(d.spec){if(!changeSpec(game,d.spec))openModal('<p>'+PANEL_UI.specBlocked+'</p><button class="gold-button" data-arena-spec="'+d.spec+'">'+PANEL_UI.specGoHome+'</button>',false,'touchhelp');events();}if('resetTalents' in d){if(!game.rpg.talents.learned.length||confirm(el.textContent.trim()+'?')){if(!resetTalents(game))toast('Talente am Clan-Treff zurücksetzen, außerhalb des Kampfes.');events();}}if(d.rewardChoice||d.confirmReward){if(d.rewardChoice&&mobile?.active){openModal(itemTooltip(game,d.rewardChoice,'reward')+'<div class="selected-item"><button class="gold-button" data-confirm-reward="'+d.rewardChoice+'" data-reward-quest="'+d.rewardQuest+'">'+PANEL_UI.chooseReward+'</button></div>',false,'inspection');paintRpg();}else{const id=d.confirmReward||d.rewardChoice,main=d.rewardQuest==='main'||String(d.rewardQuest).startsWith('main-'),ok=main?game.claimQuest(id):game.claimSideQuest(d.rewardQuest,id);events();if(ok){popups.close('dialog');popups.close('inspection');toast('Auftrag bezahlt. Dein gewähltes Teil liegt im Rucksack.');}else toast('Beim Questgeber wählen, Auftrag abschließen und einen Rucksackplatz freihalten.');}}if('activityTap' in d||d.wire!==undefined){activityInput(game,d.wire===undefined?undefined:Number(d.wire));events();}});
$('#world').addEventListener('pointermove',e=>{if(!game)return;const p=renderer.screenToWorld(e.clientX,e.clientY);if(game.aiming)game.aimPoint=p;if(e.pointerType==='touch')return;game.hover=p;const u=game.paused||game.dead?null:unitAt(game,p.x,p.y);$('#world').style.cursor=u?'pointer':'';});
$('#world').addEventListener('pointerleave',()=>{if(game){game.hover=null;game.hoverUnit=null;}$('#world').style.cursor='';});
new ResizeObserver(()=>renderer?.resize()).observe($('#gameShell'));init();
modal.addEventListener('contextmenu',e=>{const b=e.target.closest('[data-talent]');if(b){e.preventDefault();if(unlearnTalent(game,b.dataset.talent))events();}});
let tutorialUI;
function showTutorial(){if(tutorialActive(game))openModal(tutorialDialogue(game,!!mobile?.active));}
modal.addEventListener('click',e=>{if(e.target.closest('[data-tutorial-next]')){if(tutorialConfirm(game)){popups.close('dialog');events();}}});
document.addEventListener('panel-detail',e=>{const w=openModal(e.detail.html,false,'detail');w.el.querySelector('.popup-titlebar strong').textContent=e.detail.title;paintRpg();});
document.addEventListener('panel-reflow',e=>{const w=popups.get(e.detail);if(w)adaptPanel(w);});
let panelLayoutSignature='';new MutationObserver(()=>{const signature=[innerWidth,innerHeight,document.body.classList.contains('touch-mode'),document.body.classList.contains('touch-combat')].join(':');if(signature===panelLayoutSignature)return;panelLayoutSignature=signature;for(const w of popups.windows.values())adaptPanel(w);}).observe(document.body,{attributes:true,attributeFilter:['class']});
